      name: "Alirocumab",
      generic: "alirocumab",
      aliases: ["Praluent", "alirocamab", "alirocimab", "PCSK9 monoclonal antibody", "Praluent pen", "LDL receptor recycling antibody"],
      brandExamples: ["Praluent"],
